import random

GROUP = "geometry"
SKILL = "counting"


def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(10, 20)

    # Complement over a set of points with n points, where the union of two
    # chosen sets is expanded by inclusion-exclusion. The sets are triangles,
    # and their union is expanded by inclusion-exclusion.
    points = list(range(n))
    triangles = [
        [points[i], points[j], points[k]]
        for i in range(n - 2)
        for j in range(i + 1, n - 1)
        for k in range(j + 1, n)
    ]
    total = len(triangles)
    pick_1 = rng.choice(triangles)
    pick_2 = rng.choice([t for t in triangles if t != pick_1])
    union = (
        sum(len(set(pick_1).intersection(set(t))) > 0 for t in triangles)
        + sum(len(set(pick_2).intersection(set(t))) > 0 for t in triangles)
        - sum(len(set(pick_1).intersection(set(pick_2)).intersection(set(t))) > 0 for t in triangles)
    )
    answer = total - union

    # Independent route: walk every triangle in the set and test it against the
    # two chosen triangles, instead of counting by complement.
    check = 0
    for t in triangles:
        if t != pick_1 and t != pick_2:
            for u in pick_1:
                for v in pick_2:
                    if u in t and v in t:
                        check += 1
                        break
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"How many triangles in the set of triangles with vertices from {n} "
        f"distinct points contain none of the points in two given triangles? "
        f"State only the integer."
    )
    return problem, str(answer)

import random


def generate(seed):
    rng = random.Random(seed)

    # Choose two distinct integers between 1 and 10.
    x = rng.randint(1, 10)
    y = rng.randint(1, 10)
    while y == x:
        y = rng.randint(1, 10)

    # Calculate the two expressions.
    expr1 = 5 * x - 2 * y
    expr2 = 4 * y - 5 * x

    # Determine the answer based on the expressions.
    if expr1 > 0:
        answer = 1  # 5x > 2y
    elif expr1 < 0:
        answer = -1  # 5x < 2y
    else:
        answer = 0  # 5x == 2y

    # Independent route: compare the expressions directly.
    check = expr1 * expr2
    if check > 0:
        check = 1  # 5x and 2y are on the same side of zero.
    elif check < 0:
        check = -1  # 5x and 2y are on opposite sides of zero.
    else:
        check = 0  # 5x == 2y

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Given two integers x and y, calculate the expressions 5x - 2y and "
        f"4y - 5x. Determine which is greater, less than, or equal to the other. "
        f"State only the integer answer (1, 0, or -1)."
    )

    return problem, str(answer)

import random

GROUP = "number_theory"
SKILL = "transformation"

def is_prime(n):
    if n < 2:
        return False
    for d in range(2, math.isqrt(n) + 1):
        if n % d == 0:
            return False
    return True

def prime_factors(n):
    factors = set()
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.add(d)
            n //= d
        d += 1
    if n > 1:
        factors.add(n)
    return factors

def primitive_root(p):
    factors = sorted(prime_factors(p - 1))  # sorted(): determinism rule
    for g in range(2, p):
        if all(pow(g, (p - 1) // q, p) != 1 for q in factors):
            return g
    return 2

def generate(seed):
    rng = random.Random(seed)

    # INVARIANT chain, carried by construction instead of curated lists:
    #   t (= the answer) cycles over [2, 24] so answers stay evenly covered;
    #   primes are DERIVED by a trial-division filter, never typed in;
    #   p is drawn from the derived primes with t | p - 1;
    #   k = t * u with gcd(u, (p-1)/t) = 1  ->  gcd(k, p-1) = t * gcd(u, v) = t;
    #   e = t * j                           ->  t | ind(a), so x^k = a is solvable.
    t = 2 + (seed % 23)

    primes = [n for n in range(29, 294)  # widen these bounds freely
              if is_prime(n)]
    eligible = [q for q in primes if (q - 1) % t == 0]
    assert eligible, f"no prime p with {t} | p-1 in range: widen the prime range"
    p = rng.choice(eligible)

    v = (p - 1) // t
    u_options = [u for u in (1, 2, 3)
                 if t * u <= 72 and math.gcd(u, v) == 1]  # Using K_MAX as 72
    u = rng.choice(u_options)              # u = 1 always valid: never empty
    k = t * u
    e = t * rng.randint(1, (p - 2) // t)   # multiple of t in [t, p-2]

    g = primitive_root(p)
    a = pow(g, e, p)
    answer = t

    assert math.gcd(k, p - 1) == t and e % t == 0, (
        "invariant violated: gcd(k, p-1) == t and t | e must hold"
    )

    # Independent route: count the solutions of x^k = a by testing every
    # residue, instead of reading the count off gcd(k, p-1).
    check = sum(1 for x in range(p) if pow(x, k, p) == a)
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Let p = {p}, and let g = {g} be a primitive root modulo p. "
        f"For the residue a = {a}, how many residue classes x modulo {p} "
        f"satisfy x^{k} ≡ a (mod {p})?"
    )
    return problem, str(answer)

