def generate(seed):
    rng = random.Random(seed)

    # INVARIANT: The sum of the variables must equal 9, and the product must be 9.
    # The real optimum occurs when \( a = b = c = 3 \), but we are now interested
    # in finding all triples \( (a, b, c) \) that satisfy the conditions.
    m = rng.randint(2, 14)         # free parameter; widen freely
    s = 9                         # s in {9}
    k = rng.randint(1, 7)         # k >= 1 keeps every factor positive

    assert s % 3 == 0 and k >= 1, (
        "invariant violated: s must stay a multiple of 3 and k >= 1"
    )

    # Check if the product condition can be satisfied with integer values
    for a in range(1, s):
        for b in range(1, s - a):
            c = s - a - b
            if c > 0 and (a + k) * (b + k) * (c + k) == 9:
                answer = 1  # There is at least one solution (a, b, c)
                break
        else:
            continue
        break
    else:
        answer = 0  # No solution found

    # Independent route: count the number of positive integer solutions to a + b + c = 9
    # such that (a + k)(b + k)(c + k) = 9.
    count = 0
    for a in range(1, 9):
        for b in range(1, 9 - a):
            c = 9 - a - b
            if c > 0 and (a + k) * (b + k) * (c + k) == 9:
                count += 1
    assert answer == count, f"answer={answer} check={count}"

    problem = (
        f"Let \( a, b, c \) be positive real numbers with \( a + b + c = 9 \). "
        f"Find the number of triples \( (a, b, c) \) such that \( (a + k)(b + k)(c + k) = 9 \). "
        f"State only the integer."
    )

    return problem, str(answer)

