def generate(seed):
    rng = random.Random(seed)
    s = rng.randint(3, 13) * 3        # s in {6, 9, ..., 39}
    k = rng.randint(1, 7)             # k >= 1 keeps every factor positive

    assert s % 3 == 0 and k >= 1, (
        "invariant violated: s must stay a multiple of 3 and k >= 1"
    )

    max_product = (s // 3 + k) ** 3   # exact since s = 3m

    # Independent route: test every integer triple (a, b, c) where a + b + c = s.
    # Since 3 | s, the real optimum is achieved when a = b = c = s / 3, which is
    # a lattice point. Therefore, the searched maximum must equal the formula.
    def product_of_sums(a, b, c):
        return (a + k) * (b + k) * (c + k)

    check = max(
        product_of_sums(a, b, s - a - b)
        for a in range(s + 1)
        for b in range(s - a + 1)
    )
    assert max_product == check, f"max_product={max_product} check={check}"

    problem = (
        f"Let a, b, c be non-negative integers with a + b + c = {s}. "
        f"What is the maximum value of (a + {k})(b + {k})(c + {k})?"
    )

    return problem, str(max_product)

