import math

GROUP = "combinatorics"
SKILL = "counting"

def comb(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    num = math.factorial(n)
    den = math.factorial(k) * math.factorial(n - k)
    return num // den

def generate(seed):
    rng = random.Random(seed)
    m = rng.randint(2, 10)
    n = rng.randint(2, 10)

    total = m ** n

    union = 0
    for r in range(1, m):
        for k in range(1, n):
            union += (-1) ** (k - 1) * comb(m, r) * (m - r) ** (n - k)

    answer = total - union

    check = 0
    for x in range(m):
        for y in range(x + 1, m):
            for z in range(y + 1, m):
                if n == 3:
                    check += 1
                else:
                    check += comb(n, 3) * (m - 3) ** (n - 3)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"How many ways are there to place {n} points in a {m} x {m} grid "
        f"such that no two points are on the same row? State only the integer."
    )
    return problem, str(answer)

