def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(10, 20)         # free parameter; widen freely
    max_w = rng.randint(1, 10)      # w in {1, 2, ..., 10}
    max_h = rng.randint(1, 10)      # h in {1, 2, ..., 10}

    assert max_w > 0 and max_h > 0, (
        "invariant violated: max_w and max_h must stay positive"
    )

    # Calculate the number of pairs (w, h) such that w * h = max_w * max_h
    product = max_w * max_h
    count = 0
    for w in range(1, max_w + 1):
        if product % w == 0:
            h = product // w
            if 1 <= h <= max_h:
                count += 1

    answer = count

    # Independent route: count all pairs (w, h) that satisfy the constraints and the product condition
    check = 0
    for w in range(1, max_w + 1):
        for h in range(1, max_h + 1):
            if w * h == product:
                check += 1
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Let w and h be positive integers such that 1 <= w <= {max_w} and 1 <= h <= {max_h}, and w * h = {product}. "
        f"How many pairs (w, h) satisfy these conditions?"
    )

    return problem, str(answer)

