import random

GROUP = "number_theory"
SKILL = "casework"

def generate(seed):
    rng = random.Random(seed)
    # Ensure s is a multiple of 3 by choosing from the set {3, 6, 9, 12, 15, 18, 21, 24, 27, 30, 33, 36, 39, 42}
    s = rng.choice([3, 6, 9, 12, 15, 18, 21, 24, 27, 30, 33, 36, 39, 42])
    k = rng.randint(1, 7)  # k must be at least 1

    # Consider possible values for (a + k) + (b + k) + (c + k) and explore the integer partitions
    total_sum = s + 3 * k

    # Function to find all partitions of an integer `n` into `r` parts
    def partitions(n, r):
        if r == 1:
            yield [n]
        else:
            for i in range(1, n - r + 2):
                for p in partitions(n - i, r - 1):
                    yield [i] + p

    max_product = 0
    for partition in partitions(total_sum, 3):
        a_plus_k, b_plus_k, c_plus_k = partition
        product = a_plus_k * b_plus_k * c_plus_k
        if product > max_product:
            max_product = product

    # Ensure that the computed maximum product matches the formula (s/3 + k)^3
    assert max_product == (s // 3 + k) ** 3, f"max_product={max_product} expected={(s // 3 + k) ** 3}"

    problem = (
        f"Given non-negative integers a, b, and c with a + b + c = {s}, "
        f"what is the maximum value of (a + {k})(b + {k})(c + {k})?"
    )

    return problem, str(max_product)

