    factors = sorted(rng.sample([2, 3, 5, 7, 11, 13], 3))  # Selecting prime factors for a non-trivial divisor problem

    # Independent route: Calculate the total number of divisors based on the prime factorization of the number
    p, q, r = factors
    total_divisors = (n // p + n // q + n // r - n // (p * q) - n // (p * r) - n // (q * r) + n // (p * q * r))
    answer = total_divisors

    # Helper function to generate all divisors of the number n
    def get_divisors(n, factors):
        divisors = set()
        # Store the prime factorization of n
        prime_factors = {}
        temp_n = n
        for factor in factors:
            count = 0
            while temp_n % factor == 0:
                count += 1
                temp_n //= factor
            if count > 0:
                prime_factors[factor] = count

        # Generate all combinations of the exponents
        def generate_combinations(exponents):
            if not exponents:
                return [1]
            remaining = exponents[1:]
            rest = generate_combinations(remaining)
            result = []
            for i in range(exponents[0] + 1):
                for j in rest:
                    result.append(i * j)
            return result

        exponent_combinations = generate_combinations(prime_factors.values())
        for combination in exponent_combinations:
            divisor = 1
            for i in range(len(prime_factors)):
                divisor *= combination[i] ** prime_factors[list(prime_factors.keys())[i]]
            if divisor <= n:
                divisors.add(divisor)

        return sorted(divisors)

    actual_divisors = get_divisors(n, factors)
    check = sum(1 for d in actual_divisors if d % p and d % q and d % r)
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider the number {n} and its prime factors {p}, {q}, and {r}. "
        f"How many divisors of {n} are divisible by none of these primes? State only the integer."
    )

