def comb_non_adjacent(n, k):
    """Calculate the number of ways to choose k non-adjacent items from n positions."""
    if k == 0:
        return 1
    elif k == 1:
        return n
    else:
        # The number of ways to choose k non-adjacent items from n positions is comb(n - k + 1, k)
        return math.comb(n - k + 1, k)

def total_combinations(n, k):
    """Total number of ways to choose k items from n positions without any constraints."""
    return math.comb(n, k)

def invalid_combinations(n, k):
    """Calculate the number of ways to choose k items such that at least two are adjacent."""
    if k == 2:
        # For k = 2, the invalid combinations are those where the two chosen items are adjacent.
        # There are (n - 1) ways to choose 2 adjacent items from n positions.
        return n - 1
    elif k > 2:
        # For k > 2, we use the principle of inclusion-exclusion to count the invalid combinations.
        # The number of ways to choose k items with at least two adjacent is:
        # total_combinations - (number of ways to choose k non-adjacent items)
        # which is total_combinations - comb_non_adjacent(n, k)
        return total_combinations(n, k) - comb_non_adjacent(n, k)
    else:
        return 0

