        "invariant violated: s must stay a multiple of 3 and k >= 1"
    )

    # Determine the quotient and remainder when s is divided by 3k
    q, r = divmod(s, 3 * k)

    # Case 1: When r = 0, all factors are equal
    if r == 0:
