    # Independent route: recompute the max product from the quotient and remainder
    def compute_max_product(q, r):
        if r == 0:
            return (q * k + k) ** 3
        elif r == 1:
            return (q * k + k) * (q * k + k) * (q * k + k + 1)
        elif r == 2:
