def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(10, 50)  # Number of points on the circle
    k = rng.randint(3, n // 2)  # Number of positions to count

    # Base case: k = 1, which means counting every single point, resulting in exactly n ways.
    if k == 1:
        answer = n
    else:
        # Recursive definition: C(n, k) = C(n-1, k-1) + C(n-1, k)
        # Base cases: C(n, 0) = C(n, n) = 1
        def C(n, k):
            if k == 0 or k == n:
                return 1
            else:
                return C(n - 1, k - 1) + C(n - 1, k)

        answer = C(n, k)

    # Independent route: use the combination formula to count the number of combinations.
    num_solutions = math.comb(n, k)

    # Assert that the two routes give the same result.
    assert answer == num_solutions, f"answer={answer} num_solutions={num_solutions}"

    problem = (
        f"How many distinct ways are there to choose {k} positions out of {n} points equally spaced on a circle? "
        f"State only the integer."
    )

    return problem, str(answer)

